func is_amount(t):
    digit_count = 0
    dot_count = 0
    for ch in t:
        if "0123456789":has(ch):
            digit_count += 1
        elif ch is ".":
            dot_count += 1
        else:
            return false
    return digit_count > 0 and dot_count <= 1

func is_count(t):
    if t is "":
        return false
    for ch in t:
        if not "0123456789":has(ch):
            return false
    return number(t) >= 1

func money(amount):
    all_cents = floor(round(amount * 100, 6) + 0.5)
    dollars = floor(all_cents / 100)
    pennies = all_cents % 100
    if pennies < 10:
        return "$" + dollars + ".0" + pennies
    return "$" + dollars + "." + pennies

